public class InnerKnowledgeBaseVectorIngestionConfigurationFactory(Action<Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration>
{

    internal InnerKnowledgeBaseParsingConfigurationFactory ParsingConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseChunkingConfigurationFactory ChunkingConfigurationFactory { get; set; }

    protected override Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration Create()
    {
        var vectorIngestionConfigurationResult = CreateVectorIngestionConfiguration();
        factoryAction?.Invoke(vectorIngestionConfigurationResult);

        return vectorIngestionConfigurationResult;
    }

    private Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration CreateVectorIngestionConfiguration()
    {
        var vectorIngestionConfigurationResult = new Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration();

        return vectorIngestionConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.KnowledgeBaseTypes.VectorIngestionConfiguration result)
    {
        base.CreateChildren(result);

        result.ParsingConfiguration ??= ParsingConfigurationFactory?.Build();
        result.ChunkingConfiguration ??= ChunkingConfigurationFactory?.Build();
    }

} // End Of Class

